import { index, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";

export type DigestFrequency = "daily" | "weekly" | "never";

export const accounts = pgTable("accounts", {
  id: uuid("id").defaultRandom().primaryKey(),
  email: text("email").notNull().unique(),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
});

// A signed-in device. The id is generated by the application; the refresh
// token is replaced by a freshly generated one on every refresh.
export const sessions = pgTable("sessions", {
  id: uuid("id")
    .primaryKey()
    .$defaultFn(() => crypto.randomUUID()),
  accountId: uuid("account_id")
    .notNull()
    .references(() => accounts.id),
  refreshToken: text("refresh_token").notNull().unique(),
});

// One row per refresh: the token that was presented and the token that was
// issued in exchange. previous_token is indexed, not unique.
export const tokenRotations = pgTable(
  "token_rotations",
  {
    id: uuid("id").defaultRandom().primaryKey(),
    sessionId: uuid("session_id")
      .notNull()
      .references(() => sessions.id),
    previousToken: text("previous_token").notNull(),
    issuedToken: text("issued_token").notNull(),
  },
  (t) => [index("token_rotations_previous_token").on(t.previousToken)],
);

// One row per account.
export const digestPreferences = pgTable("digest_preferences", {
  accountId: uuid("account_id")
    .primaryKey()
    .references(() => accounts.id),
  frequency: text("frequency").$type<DigestFrequency>().notNull().default("weekly"),
});
